// Set the project URL here. Select the database Header Auth credential on each HTTP node.
const SUPABASE_PROJECT_URL = 'https://YOUR_PROJECT_REF.supabase.co';
const { action, dataset, month, trace_id } = $input.first().json;
const fail = (code, error) => [{ json: { ok: false, code, error } }];
if (!['live', 'demo'].includes(dataset) || typeof trace_id !== 'string' || !trace_id.trim() || trace_id.length > 200) {
  return fail('INVALID_REQUEST', 'Use dataset live or demo and a non-empty trace_id of at most 200 characters.');
}
const currentMonth = new Date().toISOString().slice(0, 7);
const validMonth = typeof month === 'string' && month.length === 7 && /^\d{4}-(0[1-9]|1[0-2])$/.test(month)
  && !month.startsWith('0000') && month <= currentMonth;
if (!((action === 'status' && month === '') || (action === 'get_report' && validMonth))) {
  return fail('INVALID_REQUEST', 'Use status with an empty month or get_report with a valid YYYY-MM through the current UTC month.');
}
const supabase_url = SUPABASE_PROJECT_URL.replace(/\/+$/, '');
if (!/^https?:\/\/[a-z0-9.-]+(?::\d{1,5})?$/i.test(supabase_url) || supabase_url.includes('YOUR_PROJECT_REF')) {
  return fail('DEPENDENCY_ERROR', 'The Supabase project URL is unconfigured.');
}
return [{ json: { ok: true, action, dataset, month, trace_id, supabase_url } }];

const { body } = $input.first().json;
const isObject = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const fail = (code, error) => [{ json: { ok: false, code, error } }];
const { dataset } = $('Settings and Validation').first().json;
if (!isObject(body) || body.dataset !== dataset || !['up', 'down', 'unknown'].includes(body.current_status)
    || !(body.latest_check === null || isObject(body.latest_check)) || !Array.isArray(body.recent_checks)) {
  return fail('DEPENDENCY_ERROR', 'Supabase returned an invalid status response.');
}
return [{ json: { ok: true, result: body } }];

const { body } = $input.first().json;
const isObject = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const fail = (code, error) => [{ json: { ok: false, code, error } }];
const isReportId = value => typeof value === 'string' && value.length === 36
  && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value);
const hasDraftHeading = text => typeof text === 'string' && text.split(/\r?\n/, 1)[0] === 'SLA GUARD CLAIM DRAFT';
const { month, dataset } = $('Settings and Validation').first().json;
if (Array.isArray(body) && body.length === 0) {
  return fail('REPORT_NOT_FOUND', 'No saved report exists for the requested month and dataset.');
}
const row = Array.isArray(body) && body.length === 1 ? body[0] : null;
const report = row?.report;
if (!isReportId(row?.id) || !Number.isSafeInteger(row.revision) || row.revision < 1 || !isObject(report)
    || report.service_id !== 'website' || report.month !== month || report.dataset !== dataset) {
  return fail('DEPENDENCY_ERROR', 'Supabase returned an invalid saved report.');
}
const claim_draft = report.is_final === true && report.unknown_seconds === 0 && report.assessment === 'breach_detected' && hasDraftHeading(row.claim_draft)
  ? row.claim_draft : null;
return [{ json: { ok: true, result: { report_id: row.id, revision: row.revision, report, claim_draft } } }];
